class Book::AccessImport
  Result = Struct.new(:accesses, :duplicate_index)

  def initialize(book, grants)
    @book, @grants = book, grants
  end

  def import
    return Result.new([], nil) if @grants.empty?

    if (bad_index = first_bad_index)
      return Result.new([], bad_index)
    end

    accesses = insert_accesses
    notify(accesses)
    Result.new(accesses, nil)
  end

  private
    def first_bad_index
      seen = {}
      existing = existing_user_ids

      @grants.each_with_index do |grant, index|
        return index unless known_level?(grant[:level])

        user_id = grant[:user_id]
        return index if user_id.nil? || seen.key?(user_id) || existing.include?(user_id)

        seen[user_id] = true
      end

      nil
    end

    def known_level?(level)
      Access.levels.key?(level.to_s)
    end

    def existing_user_ids
      @book.accesses.where(user_id: @grants.map { |grant| grant[:user_id] }).pluck(:user_id).to_set
    end

    def insert_accesses
      rows = @grants.map { |grant| { user_id: grant[:user_id], level: grant[:level].to_s } }
      result = @book.accesses.insert_all(rows, returning: %w[ id user_id book_id level created_at updated_at ])
      result.map { |row| Access.instantiate(row.stringify_keys) }
    end

    def notify(accesses)
      accesses.each { |access| Book::AccessNotificationJob.perform_later(access) }
    end
end
