class Book::AccessImport
  Result = Struct.new(:accesses, :duplicate_index)

  def initialize(book, grants)
    @book, @grants = book, grants
  end

  def import
    if (index = rejection_index)
      Result.new([], index)
    else
      Result.new(persist_and_notify, nil)
    end
  rescue ActiveRecord::RecordNotUnique
    Result.new([], rejection_index || 0)
  end

  private
    def rejection_index
      seen = {}

      @grants.each_with_index do |grant, index|
        return index unless Access.levels.key?(grant[:level].to_s)
        return index if seen[grant[:user_id]]
        seen[grant[:user_id]] = true
      end

      return if seen.empty?

      existing = @book.accesses.where(user_id: seen.keys).pluck(:user_id).to_set
      @grants.index { |grant| existing.include?(grant[:user_id]) }
    end

    def persist_and_notify
      return [] if @grants.empty?

      rows = @grants.map { |grant| { user_id: grant[:user_id], level: grant[:level].to_s } }
      @book.accesses.insert_all!(rows)

      accesses_by_user_id = @book.accesses.where(user_id: rows.map { |row| row[:user_id] }).index_by(&:user_id)
      accesses = rows.map { |row| accesses_by_user_id[row[:user_id]] }
      accesses.each { |access| Book::AccessNotificationJob.perform_later(access) }
      accesses
    end
end
